  question_text, option_a, option_b, option_c, option_d, option_e, correct_answer,
  misconception_a, misconception_b, misconception_c, misconception_d, explanation,
  source, validated, active, review_status, question_type, answer_spec, combined_eligible, context_region)
select $t$Mathematics$t$, $t$AQA$t$, 'GCSE', $t$Both$t$, $t$Trigonometry$t$, $t$Pythagoras' Theorem$t$, $t$aqa-ma-fh-trigonometry$t$, 2,
  $t$A right-angled triangle has shorter sides of 9 cm and 12 cm. How long is the hypotenuse, in cm?$t$,
  null, null, null, null, 'Not sure', null,
  null, null, null, null,
  $t$\(c^{2} = 9^{2} + 12^{2} = 81 + 144 = 225\), so \(c = \sqrt{225} = 15\,\text{cm}\).$t$,
  'ai_drafted', false, true, 'draft', 'numeric', $t${"value":15,"wrong":[{"value":21,"misconception":"This adds the sides. Pythagoras adds their squares: \\(\\sqrt{81 + 144} = \\sqrt{225} = 15\\)."},{"value":7.94,"misconception":"This subtracts the squares, which finds a shorter side. For the hypotenuse, add: \\(\\sqrt{81 + 144} = 15\\)."},{"value":225,"misconception":"225 is \\(c^{2}\\). Take the square root: \\(\\sqrt{225} = 15\\)."}]}$t$::jsonb, true, null
where not exists (select 1 from public.diagnostic_questions where subject = $t$Mathematics$t$ and question_text = $t$A right-angled triangle has shorter sides of 9 cm and 12 cm. How long is the hypotenuse, in cm?$t$);

insert into public.diagnostic_questions (
