select $t$Mathematics$t$, $t$AQA$t$, 'GCSE', $t$Higher$t$, $t$Graphs$t$, $t$Gradient$t$, $t$aqa-ma-fh-graphs$t$, 2,
  $t$What is the gradient of the straight line through \((1, 3)\) and \((5, 11)\)?$t$,
  null, null, null, null, 'Not sure', null,
  null, null, null, null,
  $t$Gradient \(= \dfrac{y_2 - y_1}{x_2 - x_1} = \dfrac{11 - 3}{5 - 1} = \dfrac{8}{4} = 2\).$t$,
  'ai_drafted', false, true, 'draft', 'numeric', $t${"value":2,"wrong":[{"value":0.5,"misconception":"This divides the change in \\(x\\) by the change in \\(y\\). Gradient \\(= \\dfrac{\\text{change in } y}{\\text{change in } x} = \\dfrac{11 - 3}{5 - 1} = 2\\)."},{"value":2.2,"misconception":"This divides one \\(y\\)-value by one \\(x\\)-value. Use the changes: \\(\\dfrac{11 - 3}{5 - 1} = \\dfrac{8}{4} = 2\\)."},{"value":8,"misconception":"8 is the change in \\(y\\). Divide by the change in \\(x\\) (4): gradient \\(= 2\\)."}]}$t$::jsonb, true, null
where not exists (select 1 from public.diagnostic_questions where subject = $t$Mathematics$t$ and question_text = $t$What is the gradient of the straight line through \((1, 3)\) and \((5, 11)\)?$t$);

