  $t$A round cocoa-drying mat has a diameter of 3 m. What is its area, in m², to 1 decimal place?$t$,
  null, null, null, null, 'Not sure', null,
  null, null, null, null,
  $t$Radius \(= 1.5\,\text{m}\). Area \(= \pi r^{2} = \pi \times 1.5^{2} = 7.07\ldots \approx 7.1\,\text{m}^{2}\).$t$,
  'ai_drafted', false, true, 'draft', 'numeric', $t${"value":7.0686,"tolerance":0.01,"wrong":[{"value":28.27,"misconception":"This uses the diameter as the radius. The radius is \\(3 \\div 2 = 1.5\\,\\text{m}\\): \\(\\pi \\times 1.5^{2} = 7.1\\,\\text{m}^{2}\\)."},{"value":9.42,"misconception":"That is the circumference (\\(\\pi d\\)). Area \\(= \\pi r^{2} = \\pi \\times 1.5^{2} = 7.1\\,\\text{m}^{2}\\)."},{"value":4.71,"misconception":"This forgets to square the radius: \\(\\pi \\times 1.5^{2} = 7.1\\,\\text{m}^{2}\\)."}]}$t$::jsonb, true, null
where not exists (select 1 from public.diagnostic_questions where subject = $t$Mathematics$t$ and question_text = $t$A round cocoa-drying mat has a diameter of 3 m. What is its area, in m², to 1 decimal place?$t$);

insert into public.diagnostic_questions (
  subject, exam_board, level, tier, topic, subtopic, spec_slug, difficulty,
  question_text, option_a, option_b, option_c, option_d, option_e, correct_answer,
  misconception_a, misconception_b, misconception_c, misconception_d, explanation,
  source, validated, active, review_status, question_type, answer_spec, combined_eligible, context_region)
select $t$Mathematics$t$, $t$AQA$t$, 'GCSE', $t$Both$t$, $t$Number — basics and operations$t$, $t$Order of Operations$t$, $t$aqa-ma-fh-number-basics$t$, 1,
  $t$Work out \(20 - 3 \times (2 + 4)^{2}\).$t$,
  null, null, null, null, 'Not sure', null,
  null, null, null, null,
  $t$Brackets: \(2 + 4 = 6\). Powers: \(6^{2} = 36\). Multiply: \(3 \times 36 = 108\). Subtract: \(20 - 108 = -88\).$t$,
  'ai_drafted', false, true, 'draft', 'numeric', $t${"value":-88,"wrong":[{"value":612,"misconception":"This works left to right: \\(20 - 3 = 17\\) first. Brackets, then powers, then multiplication: \\(20 - 3 \\times 36 = 20 - 108 = -88\\)."},{"value":-304,"misconception":"This squares \\(3 \\times 6\\). The power only applies to the bracket: \\(6^{2} = 36\\), then \\(3 \\times 36 = 108\\), so \\(20 - 108 = -88\\)."},{"value":2,"misconception":"This multiplies the bracket by 3 without squaring it. \\((2 + 4)^{2} = 36\\), so \\(20 - 108 = -88\\)."}]}$t$::jsonb, true, null
where not exists (select 1 from public.diagnostic_questions where subject = $t$Mathematics$t$ and question_text = $t$Work out \(20 - 3 \times (2 + 4)^{2}\).$t$);

